function visit(l,path,out){(l.layers||[]).forEach(k=>{if(l.type!=='SymbolInstance'&&k.frame&&(k.frame.x < -1 || k.frame.y < -1 || k.frame.x+k.frame.width>l.frame.width+1 || k.frame.y+k.frame.height>l.frame.height+1))out.push({parent:path,child:k.name,x:k.frame.x,y:k.frame.y,w:k.frame.width,h:k.frame.height,pw:l.frame.width,ph:l.frame.height});if(k.type!=='SymbolInstance')visit(k,path+'/'+k.name,out);});}doc.pages.filter(p=>/^Proto macOS /.test(p.name)).forEach(p=>p.layers.filter(l=>l.name.indexOf('Screen/macos/')===0&&l.name.split('/')[4].indexOf('settings')===0).forEach(s=>{var out=[];visit(s,s.name,out);H.out({id:s.name,overflow:out});}));